-- 011_brk_rcont_current_backfill.sql
-- =============================================================================
-- Carry Eaton/EasyPower per-breaker-style continuous rating (Access r_cont_current,
-- the field EasyPower uses to pick the ONE sensor within a borrowed SST trip-style)
-- onto tcc.brk_{mccb,pcb,iccb}_styles. Prod dropped it at the D1 load (STATE §138);
-- this re-carries it so the SST bridge can rating-narrow to the matching sensor
-- instead of surfacing the whole style sensor set. Source: D:\TCC_NEW.accdb read
-- read-only; joined on source_id (= Access ID, the rank=id key, §104). Bridged rows
-- (TMT_Use_SST<>0) only. apply_migration provides the transaction. Reversible.
-- Operator-authorized (2026-06-04). IDEMPOTENT (ADD COLUMN IF NOT EXISTS + UPDATE).
-- =============================================================================

ALTER TABLE tcc.brk_mccb_styles ADD COLUMN IF NOT EXISTS r_cont_current numeric;
ALTER TABLE tcc.brk_pcb_styles ADD COLUMN IF NOT EXISTS r_cont_current numeric;
ALTER TABLE tcc.brk_iccb_styles ADD COLUMN IF NOT EXISTS r_cont_current numeric;

UPDATE tcc.brk_mccb_styles t SET r_cont_current = v.rcc
